    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int numberInput = scan.nextInt();
        String inputString = scan.next();
        int maxSequence = 0;
        int currentSequence = 0;
        int underscoreSum = 0;
        boolean inParenthesesFlag = false;
        boolean wasLetter = false;

        for (int i = 0; i < inputString.length(); i++) {
            char c = inputString.charAt(i);
            if ((c > 96 && c < 123) || (c > 64 && c < 91)) {
                if (inParenthesesFlag && !wasLetter)
                    underscoreSum++;
                if (!inParenthesesFlag)
                    currentSequence++;
                if (currentSequence > maxSequence)
                    maxSequence = currentSequence;
                wasLetter = true;
            } else if (c == '_') {
                wasLetter = false;
                if (currentSequence > maxSequence)
                    maxSequence = currentSequence;
                currentSequence = 0;
            } else if (c == '(') {
                wasLetter = false;
                inParenthesesFlag = true;
                if (currentSequence > maxSequence)
                    maxSequence = currentSequence;
                currentSequence = 0;
            } else if (c == ')') {
                inParenthesesFlag = false;
                wasLetter = false;
                if (currentSequence > maxSequence)
                    maxSequence = currentSequence;
                currentSequence = 0;
            }
        }
        System.out.println(maxSequence + " " + underscoreSum);
        scan.close();
    }
}
